namespace ghidra.app.plugin.core.bookmark;



using docking;
using docking;
using docking.action;
using ghidra.app.context;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.util;

/**
 * <CODE>AddBookmarkAction</CODE> allows the user to add a Note bookmark at the current location.
 */
class AddBookmarkAction : DockingAction {
	/** the plugin associated with this action. */
	BookmarkPlugin plugin;

	/**
	 * Creates a new action with the given name and associated to the given plugin.
	 * 
	 * @param name the name for this action.
	 * @param plugin the plugin this action is associated with.
	 */
	AddBookmarkAction(BookmarkPlugin plugin) : base("Add Bookmark", plugin.getName())
    {
		this.plugin = plugin;
		setDescription("Add Notes bookmark to current location");
// ACTIONS - auto generated
		setPopupMenuData(new MenuData(new string[] { "Bookmark..." }, null, "Bookmark"));
		setKeyBindingData(
			new KeyBindingData(KeyEvent.VK_D, DockingUtils.CONTROL_KEY_MODIFIER_MASK));

	}

	/**
	 * Method called when the action is invoked.
	 * 
	 * @param ActionEvent details regarding the invocation of this action
	 */
	/* @Override */
	public void actionPerformed(ActionContext context) {
		plugin.showAddBookmarkDialog(getAddress(context), getProgram(context));
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (context == null) {
			return false;
		}
		return getAddress(context) != null && getProgram(context) == plugin.getCurrentProgram();
	}

	private Address getAddress(ActionContext context) {
		object contextObject = context.getContextObject();
		if (typeof(MarkerLocation).isAssignableFrom(contextObject.GetType())) {
			return ((MarkerLocation) contextObject).getAddr();
		}
		else if (context is ListingActionContext) {
			return ((ListingActionContext) context).getAddress();
		}
		return null;
	}

	private Program getProgram(ActionContext context) {
		object contextObject = context.getContextObject();
		if (typeof(MarkerLocation).isAssignableFrom(contextObject.GetType())) {
			return ((MarkerLocation) contextObject).getProgram();
		}
		else if (context is ListingActionContext) {
			return ((ListingActionContext) context).getProgram();
		}
		return null;
	}
}
